-- ----------------------------
-- Table structure for uw_activity
-- ----------------------------
DROP TABLE IF EXISTS `uw_activity`;
CREATE TABLE `uw_activity` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `title` varchar(50) DEFAULT NULL COMMENT '标题',
  `fullTitle` varchar(50) DEFAULT NULL COMMENT '标题全称',
  `type` int(2) DEFAULT '0' COMMENT '1:首冲;\n            2:7天登陆\n            3:限时抢购\n            4:累充福利\n            5:消费有礼\n            6:升级有奖\n            7:兑换码\n            ',
  `iconType` int(2) DEFAULT '0' COMMENT 'icon类型',
  `tiIconType` int(2) DEFAULT '0' COMMENT '标题icon类型',
  `startTime` datetime DEFAULT NULL COMMENT '开始时间',
  `endTime` datetime DEFAULT NULL COMMENT '结束时间',
  `items` text COMMENT '物品',
  `randomHeroes` varchar(500) DEFAULT NULL COMMENT '随机英雄数据',
  `exValues` text COMMENT '扩展值',
  `exValues2` text COMMENT '扩展值2',
  `exValues3` text COMMENT '扩展值3',
  `content` text COMMENT '内容',
  `isOpen` int(2) DEFAULT '0' COMMENT '是否开启',
  `sort` int(11) DEFAULT '0' COMMENT '排序',
  `exData` text COMMENT '活动额外信息 {"1":"jchd"}',
  `templateId` int(11) DEFAULT '0' COMMENT '活动模板ID',
  `note` text COMMENT '备注',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4022 DEFAULT CHARSET=utf8mb4;

-- ----------------------------
-- Records of uw_activity
-- ----------------------------

-- ----------------------------
-- Table structure for uw_activity_record
-- ----------------------------
DROP TABLE IF EXISTS `uw_activity_record`;
CREATE TABLE `uw_activity_record` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `userId` int(11) DEFAULT NULL COMMENT '用户id',
  `activityId` int(11) DEFAULT NULL COMMENT '活动id',
  `activityType` int(11) DEFAULT NULL COMMENT '活动类型',
  `userLvl` int(11) DEFAULT NULL COMMENT '用户等级',
  `userVip` int(11) DEFAULT NULL COMMENT '用户vip',
  `costDiamond` int(11) DEFAULT NULL COMMENT '消耗钻石数量',
  `getDiamond` int(11) DEFAULT NULL COMMENT '获取钻石数量',
  `joinCount` int(11) DEFAULT NULL COMMENT '参与活动次数',
  `addTime` datetime DEFAULT NULL COMMENT '首次参加时间',
  `updateTime` datetime DEFAULT NULL COMMENT '最后参与时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COMMENT='游戏-活动记录';

-- ----------------------------
-- Records of uw_activity_record
-- ----------------------------

-- ----------------------------
-- Table structure for uw_arena
-- ----------------------------
DROP TABLE IF EXISTS `uw_arena`;
CREATE TABLE `uw_arena` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `userId` int(11) DEFAULT '0' COMMENT '用户id',
  `rank` int(11) DEFAULT '0' COMMENT '排名',
  `highRank` int(11) DEFAULT '0' COMMENT '历史最高排名',
  `fightRanks` varchar(50) DEFAULT NULL COMMENT '挑战排名',
  `reNumData` varchar(200) DEFAULT NULL COMMENT '挑战次数数据',
  `awardData` varchar(200) DEFAULT NULL COMMENT '奖励数据',
  `winCount` int(11) DEFAULT '0' COMMENT '累计胜场',
  `conWinCount` int(11) DEFAULT '0' COMMENT '连胜场数',
  `maxConWinCount` int(11) DEFAULT '0' COMMENT '最大连胜场数',
  PRIMARY KEY (`id`),
  KEY `uw_arena_uid` (`userId`),
  KEY `uw_arena_rank` (`rank`)
) ENGINE=InnoDB AUTO_INCREMENT=2252 DEFAULT CHARSET=utf8mb4;

-- ----------------------------
-- Records of uw_arena
-- ----------------------------

-- ----------------------------
-- Table structure for uw_arena_bak
-- ----------------------------
DROP TABLE IF EXISTS `uw_arena_bak`;
CREATE TABLE `uw_arena_bak` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `userId` int(11) DEFAULT '0' COMMENT '用户id',
  `rank` int(11) DEFAULT '0' COMMENT '排名',
  `highRank` int(11) DEFAULT '0' COMMENT '历史最高排名',
  `fightRanks` varchar(50) DEFAULT NULL COMMENT '挑战排名',
  `reNumData` varchar(200) DEFAULT NULL COMMENT '挑战次数数据',
  `awardData` varchar(200) DEFAULT NULL COMMENT '奖励数据',
  `winCount` int(11) DEFAULT '0' COMMENT '累计胜场',
  `conWinCount` int(11) DEFAULT '0' COMMENT '连胜场数',
  `maxConWinCount` int(11) DEFAULT '0' COMMENT '最大连胜场数',
  PRIMARY KEY (`id`),
  KEY `uw_arena_uid` (`userId`),
  KEY `uw_arena_rank` (`rank`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

