-- ----------------------------
-- Table structure for uw_arena_record
-- ----------------------------
DROP TABLE IF EXISTS `uw_arena_record`;
CREATE TABLE `uw_arena_record` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `userId` int(11) DEFAULT NULL COMMENT '用户id',
  `userLvl` int(11) DEFAULT '0' COMMENT '用户等级',
  `userIconId` int(4) DEFAULT NULL COMMENT '用户头像',
  `userName` varchar(20) DEFAULT NULL COMMENT '用户名字',
  `userWinCount` int(11) DEFAULT NULL COMMENT '用户胜场',
  `enemyId` int(11) DEFAULT NULL COMMENT '对手id',
  `enemyLvl` int(4) DEFAULT '0' COMMENT '对手等级',
  `enemyIconId` int(4) DEFAULT NULL COMMENT '对手头像',
  `enemyName` varchar(20) DEFAULT NULL COMMENT '对手名字',
  `enemyWinCount` int(11) DEFAULT NULL COMMENT '对手胜场',
  `isWin` int(2) DEFAULT '0' COMMENT '是否胜利',
  `fightTime` datetime DEFAULT NULL COMMENT '挑战时间',
  `fightData` text COMMENT '战斗数据',
  `fightType` int(2) DEFAULT '1',
  `isDeal` int(2) DEFAULT '0',
  `isRead` int(2) DEFAULT '0',
  `isRevenge` int(2) DEFAULT '0' COMMENT '是否复仇',
  PRIMARY KEY (`id`),
  KEY `uw_arena_record_uid` (`userId`),
  KEY `uw_arena_record_eid` (`enemyId`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COMMENT='排位赛挑战记录';

