-- ----------------------------
-- Table structure for uw_bonus_draw
-- ----------------------------
DROP TABLE IF EXISTS `uw_bonus_draw`;
CREATE TABLE `uw_bonus_draw` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `userId` int(11) NOT NULL,
  `drawAmount` int(11) NOT NULL COMMENT '本次提取额',
  `beforeDraw` int(11) NOT NULL COMMENT '提取前金额',
  `afterDraw` int(11) NOT NULL COMMENT '提取后的金额',
  `createTime` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_userId` (`userId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='提取表，用户的提取记录';

-- ----------------------------
-- Records of uw_bonus_draw
-- ----------------------------

-- ----------------------------
-- Table structure for uw_bonus_event
-- ----------------------------
DROP TABLE IF EXISTS `uw_bonus_event`;
CREATE TABLE `uw_bonus_event` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `userId` int(11) NOT NULL COMMENT '下家的ID',
  `inviterUserId` int(11) NOT NULL COMMENT '上家的ID',
  `eventType` varchar(45) NOT NULL COMMENT '事件类型：LEVELUP, RECHARGE',
  `reference` int(11) NOT NULL DEFAULT '0' COMMENT '充值时金额，或升级时的目标等级',
  `shareAmount` int(11) NOT NULL DEFAULT '0' COMMENT '当前事件贡献给上级的金额',
  `createTime` datetime DEFAULT NULL COMMENT '事件发生的时间',
  PRIMARY KEY (`id`),
  KEY `idx_userId` (`userId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='下家贡献的流水表';

-- ----------------------------
-- Records of uw_bonus_event
-- ----------------------------

-- ----------------------------
-- Table structure for uw_bonus_relation
-- ----------------------------
DROP TABLE IF EXISTS `uw_bonus_relation`;
CREATE TABLE `uw_bonus_relation` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `userId` int(11) NOT NULL COMMENT '分享者的ID',
  `inviteeUserId` int(11) NOT NULL COMMENT '被邀请的用户的ID',
  `amount` int(11) NOT NULL DEFAULT '0' COMMENT '被邀请的用户累计贡献',
  `isBreak` int(11) NOT NULL DEFAULT '0' COMMENT '关系是否已解除',
  `createTime` datetime DEFAULT NULL COMMENT '被邀请的用户进入时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_inviteeUserId` (`inviteeUserId`),
  KEY `idx_userId` (`userId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='好友关系表';

-- ----------------------------
-- Records of uw_bonus_relation
-- ----------------------------

-- ----------------------------
-- Table structure for uw_bonus_share
-- ----------------------------
DROP TABLE IF EXISTS `uw_bonus_share`;
CREATE TABLE `uw_bonus_share` (
  `userId` int(11) NOT NULL DEFAULT '0' COMMENT '用户角色id',
  `shareKey` varchar(50) NOT NULL DEFAULT '' COMMENT '分享用的key，用来唯一代表该用户',
  `balance` int(11) NOT NULL DEFAULT '0' COMMENT '仍未提取的金额',
  `amountDraw` int(11) NOT NULL DEFAULT '0' COMMENT '已提取的金额',
  `relationCount` int(11) NOT NULL DEFAULT '0' COMMENT '下家数量',
  `gifted` int(11) NOT NULL DEFAULT '0' COMMENT '首次分享是否已经奖励了',
  `createTime` datetime DEFAULT NULL,
  PRIMARY KEY (`userId`),
  KEY `idx_shareKey` (`shareKey`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='分红主表，每个分享过链接的用户一条记录';

-- ----------------------------
-- Records of uw_bonus_share
-- ----------------------------

-- ----------------------------
-- Table structure for uw_boss
-- ----------------------------
DROP TABLE IF EXISTS `uw_boss`;
CREATE TABLE `uw_boss` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `bossId` int(11) DEFAULT NULL COMMENT 'bossId',
  `startTime` datetime DEFAULT NULL COMMENT '开始时间',
  `endTime` datetime DEFAULT NULL COMMENT '结束时间',
  `killUserId` int(11) DEFAULT '0' COMMENT '击杀人的id',
  `deathTime` datetime DEFAULT NULL COMMENT '死亡时间',
  `status` int(4) DEFAULT '0' COMMENT '状态 0:未开启 1:开启中',
  `lastIsWin` int(4) DEFAULT '0' COMMENT '最后一次是否胜利',
  `resultData` text COMMENT '结算数据',
  `isPrize` int(2) DEFAULT '0' COMMENT '是否结算奖励',
  `limitStartTime` datetime DEFAULT NULL COMMENT '限时开启时间',
  `limitEndTime` datetime DEFAULT NULL COMMENT '限时结束时间',
  `isLimit` int(2) DEFAULT '0' COMMENT '是否限时',
  `type` int(4) DEFAULT '0' COMMENT '类型',
  `originBossId` int(11) DEFAULT '0' COMMENT '原始bossId',
  `deathBossId` int(11) DEFAULT '0' COMMENT '类型',
  `repeatCount` int(6) DEFAULT '0' COMMENT '复活次数',
  `repeatTime` datetime DEFAULT NULL COMMENT '最后复活时间',
  `callArr` varchar(500) DEFAULT NULL COMMENT '召唤数据',
  `week` int(4) DEFAULT '0' COMMENT '周几',
  `errData` int(4) DEFAULT '0' COMMENT '周几',
  PRIMARY KEY (`id`),
  KEY `uw_boss_bossid` (`bossId`)
) ENGINE=InnoDB AUTO_INCREMENT=53 DEFAULT CHARSET=utf8mb4 COMMENT='世界BOSS';

-- ----------------------------
-- Records of uw_boss
-- ----------------------------

