  `status` int(4) DEFAULT '0' COMMENT '状态 0:未开启 1:开启中',
  `lastIsWin` int(4) DEFAULT '0' COMMENT '最后一次是否胜利',
  `resultData` text COMMENT '结算数据',
  `isPrize` int(2) DEFAULT '0' COMMENT '是否结算奖励',
