  `lootResource` int(11) DEFAULT '0' COMMENT '今日掠夺储量',
  `beLootResource` int(11) DEFAULT '0' COMMENT '今日被劫储量',
  `defeseData` text COMMENT '守卫玩家数据',
  `defeseRecordArr` text COMMENT '防守记录',
  `lootRecordArr` text COMMENT '掠夺成功记录',
  `points` int(11) DEFAULT '0' COMMENT '累计积分',
  `todayPoints` int(11) DEFAULT '0' COMMENT '今日积分',
  `buffLvl` int(11) DEFAULT '0' COMMENT 'buff等级',
  `buffExpc` int(11) DEFAULT '0' COMMENT 'buff经验',
  `buffBase` int(11) DEFAULT '0' COMMENT 'buff基础值',
  `lootUserData` text COMMENT '掠夺别的服务器用户数据 {服务器id:{用户id:[次数],....},...}',
  `breakTimeData` varchar(500) DEFAULT NULL COMMENT '守卫击破时间数据{门口:时间}',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='游戏-国库信息(CoffersEntity)';

