  `timeArr` text COMMENT '子副本挑战时间列',
  `copyStar` text COMMENT '子副本星级',
  `finished` int(1) DEFAULT '0' COMMENT '主副本是否已经通过',
  `isPickAward` varchar(256) DEFAULT NULL COMMENT '是否领取通关奖励[0,0,1]',
