  `resetTime` datetime DEFAULT NULL COMMENT '购买时间',
  `readObj` text COMMENT '查看数据{副本id:是否阅读}',
  PRIMARY KEY (`id`,`userId`),
  KEY `uw_copy_progress_uid` (`userId`)
