  `employId` int(11) DEFAULT NULL COMMENT '雇佣id',
  `heroId` int(11) DEFAULT NULL COMMENT '雇佣英雄id',
  `items` varchar(64) DEFAULT NULL COMMENT '物品',
  `recordDate` datetime DEFAULT NULL COMMENT '记录日期',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4;

-- ----------------------------
-- Records of uw_employrewardrecord
-- ----------------------------

-- ----------------------------
-- Table structure for uw_expedition
-- ----------------------------
DROP TABLE IF EXISTS `uw_expedition`;
CREATE TABLE `uw_expedition` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `userId` int(11) DEFAULT '0' COMMENT '用户id',
  `stageId` int(7) DEFAULT '0' COMMENT '关卡数',
  `fightCount` int(7) DEFAULT '0' COMMENT '挑战次数',
  `soulCount` int(7) DEFAULT '0' COMMENT '元婴召唤次数',
  `buyFightCount` int(7) DEFAULT '0' COMMENT '购买挑战次数',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ----------------------------
-- Records of uw_expedition
-- ----------------------------

-- ----------------------------
-- Table structure for uw_expedition_hero
-- ----------------------------
DROP TABLE IF EXISTS `uw_expedition_hero`;
CREATE TABLE `uw_expedition_hero` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `userId` int(11) DEFAULT '0' COMMENT '用户id',
  `tempId` int(6) DEFAULT '0' COMMENT '模板id',
  `quality` int(4) DEFAULT '0' COMMENT '品阶',
  `intensifyArr` varchar(200) DEFAULT NULL COMMENT '强化[等级,等级,...] 下标对应装备位置',
  `starArr` varchar(200) DEFAULT NULL COMMENT '星级[星级,星级,...] 下标对应装备位置',
  `gemArr` varchar(200) DEFAULT NULL COMMENT '宝石[id,id,id,...]下标对应装备位置',
  `wingArr` varchar(200) DEFAULT NULL COMMENT '翅膀[id,等级,星级,当前星经验,左翅强化等级,右翅强化等级]',
  `expc` int(7) DEFAULT '0' COMMENT '经验',
  `lvl` int(4) DEFAULT '0' COMMENT '等级',
  `equipData` varchar(500) DEFAULT NULL COMMENT '{"部位":物品id,....}',
  `skillLvlArr` varchar(200) DEFAULT NULL COMMENT '[技能1等级,技能2等级...]',
  `propArr` varchar(700) DEFAULT NULL COMMENT '最终属性组[值,值]',
  `realmLvl` int(4) DEFAULT '0' COMMENT '境界等级',
  `realmArr` varchar(200) DEFAULT NULL COMMENT '境界符文组  [0,1,2,3,4,5]',
  `sex` int(4) DEFAULT '1' COMMENT '性别 1:男 2:女',
  `combat` int(11) DEFAULT '0' COMMENT '战斗力',
  `refineArr` varchar(200) DEFAULT NULL COMMENT '装备精炼[等级,等级,...] 下标对应装备位置',
  `starTopArr` varchar(100) DEFAULT NULL COMMENT '升星突破[升星突破重数,升星突破重数,...] 下标对应装备位置',
  `talismanAdorn` int(7) DEFAULT NULL COMMENT '法宝佩戴',
  `talismanData` text COMMENT '法宝数据{法宝id:[等级,资质,星级,最高星级,{星级:技能id,星级:技能id,...},临时资质],法宝id:[等级,资质,星级,最高星级,{星级:技能id,星级:技能id,...},临时资质],....}',
  `talismanFg` varchar(500) DEFAULT NULL COMMENT '法宝共鸣{共鸣id:[0,1],共鸣id:[1,0],...}',
  `wingSumLvl` int(7) DEFAULT NULL COMMENT '翅膀等级*100+星数',
  `gemSumLvl` int(7) DEFAULT NULL COMMENT '宝石总等级',
  `realmSumLvl` int(7) DEFAULT NULL COMMENT '境界等级 * 100 + 已装备个数',
  `fightSort` int(4) DEFAULT NULL COMMENT '出战顺序',
  `soulArr` varchar(200) DEFAULT NULL COMMENT '{"元婴id":[物品id,剩余血量,今日是否有穿戴过]}',
  `wearSoulId` int(11) DEFAULT NULL,
  `recordTime` datetime DEFAULT NULL COMMENT '记录时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ----------------------------
-- Records of uw_expedition_hero
-- ----------------------------

