-- ----------------------------
-- Table structure for uw_game_common
-- ----------------------------
DROP TABLE IF EXISTS `uw_game_common`;
CREATE TABLE `uw_game_common` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `highCopyId` int(11) DEFAULT '0',
  `isOpenBoss` int(2) DEFAULT '1' COMMENT '是否开放boss',
  `fakeData` text,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='游戏-公用(GameCommonEntity)';

