-- ----------------------------
-- Table structure for uw_game_record
-- ----------------------------
DROP TABLE IF EXISTS `uw_game_record`;
CREATE TABLE `uw_game_record` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `userId` int(11) DEFAULT NULL COMMENT '用户id',
  `recordTime` datetime DEFAULT NULL COMMENT '日期',
  `loginCount` int(11) DEFAULT NULL COMMENT '登录次数',
  `copyCount` int(11) DEFAULT NULL COMMENT '挑战副本次数',
  `wipeCount` int(11) DEFAULT NULL COMMENT '刷野次数',
  `pkCount` int(11) DEFAULT NULL COMMENT 'pk次数',
  `rechargeCount` int(11) DEFAULT NULL COMMENT '充值次数',
  `rechargeSum` int(11) DEFAULT NULL COMMENT '充值总金额',
  `rechargeRecord` text COMMENT '充值记录\n                        {"id":充值次数,"id":充值次数,.............}',
  `shopRecord` text COMMENT '商店记录\n                        {"id":[今日购买次数,历史购买总次数],{"id":[今日购买次数,历史购买总次数],.............}',
  `costGoldRecord` text COMMENT '消耗金币记录\n                        {"id":金币数量,"id":金币数量,.............}',
  `costDiamondRecord` text COMMENT '消耗钻石记录\n                        {"id":钻石数量,"id":钻石数量,.............}',
  `costDiamondRecord1` text COMMENT '消耗钻石记录1',
  `costDiamondRecord2` text COMMENT '消耗钻石记录2',
  `getDiamondRecord` text COMMENT '获取钻石记录\n                        {"id":钻石数量,"id":钻石数量,.............}',
  `getDiamondRecord1` text COMMENT '获取钻石记录1',
  `getDiamondRecord2` text COMMENT '获取钻石记录2',
  `channelId` int(11) DEFAULT NULL COMMENT '渠道号',
  `serverId` int(11) DEFAULT NULL COMMENT '服务器id',
  `jjcPkCount` int(11) DEFAULT NULL COMMENT '������pk����',
  `labaCount` int(4) DEFAULT NULL,
  `costDScoreNum` int(11) DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `game_record_userId_recordtime` (`userId`,`recordTime`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='用户每日数据记录';

-- ----------------------------
-- Records of uw_game_record
-- ----------------------------

-- ----------------------------
-- Table structure for uw_guild
-- ----------------------------
DROP TABLE IF EXISTS `uw_guild`;
CREATE TABLE `uw_guild` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `name` varchar(32) NOT NULL COMMENT '公会名称',
  `iconId` int(11) DEFAULT NULL COMMENT '公会旗号id',
  `chairmanId` int(11) DEFAULT NULL COMMENT '会长id',
  `viceChairmanId` varchar(32) DEFAULT NULL COMMENT '副会长ids',
  `guildPopulation` int(11) DEFAULT '1' COMMENT '公会人数',
  `addUpAct` int(8) DEFAULT '0' COMMENT '累计贡献值',
  `joinCon` int(4) DEFAULT '0' COMMENT '加入条件',
  `joinLvl` int(4) DEFAULT '0' COMMENT '加入最低等级',
  `lvl` int(4) DEFAULT '0' COMMENT '公会等级',
  `notice` varchar(100) DEFAULT NULL COMMENT '公会公告',
  `note` text COMMENT '公会日志',
  `appliedMembers` text COMMENT '申请入会人员',
  `numbersArr` varchar(50) DEFAULT NULL COMMENT '每天能开除的会员数量',
  `lastExpelTime` datetime DEFAULT NULL COMMENT '最后开除成员时间',
  `ennobleData` varchar(100) DEFAULT NULL COMMENT '爵位数据 ',
  `guildCopyData` text COMMENT '{bossId:[进度,最后结算时间],bossId:[进度,最后结算时间],...}',
  `resetCount` int(4) DEFAULT '0' COMMENT '副本重置次数',
  `resetTime` datetime DEFAULT NULL COMMENT '副本重置时间',
  `lastLgTime` datetime DEFAULT '2016-04-25 19:53:57',
  `todayHyd` int(11) DEFAULT '0' COMMENT '日活跃度',
  `weekHyd` int(11) DEFAULT '0' COMMENT '周活跃度',
  `weekHydRefreshTime` datetime DEFAULT NULL,
  `todayHydRefreshTime` datetime DEFAULT NULL,
  `hydData` varchar(500) DEFAULT NULL COMMENT '活跃度数据{"id":次数}',
  `fuli` int(11) DEFAULT '0' COMMENT '日福利值',
  `hydLuckyName` varchar(32) DEFAULT NULL COMMENT '日活跃幸运用户',
  `wareHouse` text,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='公会';

-- ----------------------------
-- Records of uw_guild
-- ----------------------------

-- ----------------------------
-- Table structure for uw_guildbattle_record
