DROP TABLE IF EXISTS `uw_guildbattle_record`;
CREATE TABLE `uw_guildbattle_record` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `battleData` text COMMENT '公会战数',
  `battleGuild` text COMMENT '参与公会',
  `battleUser` text COMMENT '参与玩家',
  `guildId` int(11) DEFAULT '0' COMMENT '胜利公会ID',
  `guildName` varchar(50) DEFAULT NULL COMMENT '胜利公会名称',
  `chairmanId` int(11) DEFAULT NULL COMMENT '会长id',
  `chairmanName` varchar(50) DEFAULT NULL COMMENT '会长名',
  `recordTime` datetime DEFAULT NULL COMMENT '记录时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2377 DEFAULT CHARSET=utf8mb4;

-- ----------------------------
-- Records of uw_guildbattle_record
