-- ----------------------------
-- Table structure for uw_guildwar_record
-- ----------------------------
DROP TABLE IF EXISTS `uw_guildwar_record`;
CREATE TABLE `uw_guildwar_record` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `recordData` longtext COMMENT '记录数据',
  `recordTime` datetime DEFAULT NULL COMMENT '记录时间',
  `lastRankData` mediumtext COMMENT '结束排名数据',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='游戏-行会战记录(GuildWarRecord)';

