-- ----------------------------
-- Table structure for uw_guild_bak
-- ----------------------------
DROP TABLE IF EXISTS `uw_guild_bak`;
CREATE TABLE `uw_guild_bak` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `chairmanId` int(11) DEFAULT NULL COMMENT '会长id',
  `lvl` int(4) DEFAULT '0' COMMENT '公会等级',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='公会。';

