-- ----------------------------
-- Table structure for uw_guild_giftbox
-- ----------------------------
DROP TABLE IF EXISTS `uw_guild_giftbox`;
CREATE TABLE `uw_guild_giftbox` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '礼盒id',
  `guildId` int(11) DEFAULT '0' COMMENT '公会id',
  `giftBoxId` int(11) DEFAULT '0' COMMENT '礼包宝箱id',
  `userId` int(11) DEFAULT '0' COMMENT '发送者id',
  `userName` varchar(64) DEFAULT NULL COMMENT '发送者名称',
  `sendTime` datetime DEFAULT NULL COMMENT '发送时间',
  `endTime` datetime DEFAULT NULL COMMENT '结束时间',
  `recvers` text COMMENT '领取者列表[id1,id2,...]',
  PRIMARY KEY (`id`),
  KEY `guild_idx` (`guildId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='行会礼盒';

