-- ----------------------------
-- Table structure for uw_guild_personal
-- ----------------------------
DROP TABLE IF EXISTS `uw_guild_personal`;
CREATE TABLE `uw_guild_personal` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '公会个人信息id',
  `userId` int(11) NOT NULL COMMENT '用户id',
  `guildId` int(11) DEFAULT '0' COMMENT '公会id',
  `position` int(4) DEFAULT '0' COMMENT '职务',
  `viceTime` datetime DEFAULT NULL COMMENT '被提升为副会长的时间',
  `todayAct` int(11) DEFAULT '0' COMMENT '今天贡献值',
  `noticeCount` int(4) DEFAULT '0' COMMENT '今天公告次数',
  `exitGuildCount` int(4) DEFAULT '0' COMMENT '今天退会次数',
  `lotteryCount` int(4) DEFAULT '0' COMMENT '今日抽奖次数',
  `actLastTime` datetime DEFAULT NULL COMMENT '贡献上一次刷新时间',
  `addUpAct` int(11) DEFAULT '0' COMMENT '累计贡献值',
  `outMsg` varchar(100) DEFAULT NULL COMMENT '退会信息',
  `appliedMsg` varchar(100) DEFAULT NULL COMMENT '申请信息',
  `actData` varchar(500) DEFAULT NULL COMMENT '格式:{"贡献id":[次数]}',
  `guildAct` int(11) DEFAULT '0' COMMENT '当前公会贡献',
  `lastQuipGuildTime` datetime DEFAULT NULL COMMENT '最后退会时间',
  `ennoble` int(4) DEFAULT '0' COMMENT '爵位',
  `joinTime` datetime DEFAULT NULL,
  `giftData` varchar(500) DEFAULT NULL COMMENT '公会礼包{"id":[是否已完成,是否已领]}',
  `weekHydChests` varchar(200) DEFAULT NULL COMMENT '周活跃度宝箱[是否领过索引,,]',
  `todayHydChests` varchar(200) DEFAULT NULL COMMENT '周活跃度宝箱[是否领过索引,,]',
  `weekRefreshTime` datetime DEFAULT NULL,
  `actCrit` int(2) DEFAULT '0' COMMENT '下次是否捐献暴击',
  `fuliChests` varchar(200) DEFAULT NULL COMMENT '日捐献宝箱[是否领过索引,,]',
  PRIMARY KEY (`id`),
  KEY `uw_guild_personal_uid` (`userId`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='公会个人信息';

-- ----------------------------
-- Records of uw_guild_personal
-- ----------------------------

