DROP TABLE IF EXISTS `uw_heart_stunt`;
CREATE TABLE `uw_heart_stunt` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '公会个人信息id',
  `userId` int(11) NOT NULL COMMENT '用户id',
  `stateArr` varchar(100) DEFAULT NULL COMMENT '境界数据\n            境界槽位对应选择的心法[心法id,心法id,...]',
  `heartLvlArr` varchar(100) DEFAULT NULL COMMENT '心法等级数据\n            境界槽位下标对应心法的等级[lvl,lvl,...]',
  PRIMARY KEY (`id`),
  KEY `uw_heart_stunt_uid` (`userId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='心法神功';

