-- ----------------------------
-- Table structure for uw_hero
-- ----------------------------
DROP TABLE IF EXISTS `uw_hero`;
CREATE TABLE `uw_hero` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `userId` int(11) DEFAULT '0' COMMENT '用户id',
  `tempId` int(6) DEFAULT '0' COMMENT '模板id',
  `quality` int(4) DEFAULT '0' COMMENT '品阶',
  `intensifyArr` varchar(200) DEFAULT NULL COMMENT '强化[等级,等级,...] 下标对应装备位置',
  `starArr` varchar(200) DEFAULT NULL COMMENT '星级[星级,星级,...] 下标对应装备位置',
  `gemArr` varchar(200) DEFAULT NULL COMMENT '宝石[id,id,id,...]下标对应装备位置',
  `enchantArr` varchar(200) DEFAULT NULL COMMENT '装备附魔等级[等级,等级,...] 下标对应装备位置',
  `wingArr` varchar(200) DEFAULT NULL COMMENT '翅膀[id,等级,星级,当前星经验]',
  `expc` int(7) DEFAULT '0' COMMENT '经验',
  `lvl` int(4) DEFAULT '0' COMMENT '等级',
  `equipData` varchar(500) DEFAULT NULL COMMENT '{"部位":物品id,....}',
  `skillLvlArr` varchar(200) DEFAULT NULL COMMENT '[技能1等级,技能2等级...]',
  `propArr` varchar(700) DEFAULT NULL COMMENT '属性组',
  `realmLvl` int(4) DEFAULT '0' COMMENT '境界等级',
  `realmArr` varchar(200) DEFAULT NULL COMMENT '境界符文组',
  `sex` int(4) DEFAULT '1' COMMENT '性别',
  `combat` int(11) DEFAULT '0' COMMENT '战斗力',
  `refineArr` varchar(200) DEFAULT NULL COMMENT '装备精炼',
  `starTopArr` varchar(100) DEFAULT NULL COMMENT '升星突破',
  `talismanAdorn` int(7) DEFAULT NULL COMMENT '法宝佩戴',
  `talismanData` text COMMENT '法宝数据{法宝id:[等级,资质,星级,最高星级,{星级:技能id,星级:技能id,...},临时资质],法宝id:[等级,资质,星级,最高星级,{星级:技能id,星级:技能id,...},临时资质],....}',
  `talismanFg` varchar(500) DEFAULT NULL COMMENT '法宝共鸣{共鸣id:[0,1],共鸣id:[1,0],...}',
  `wingSumLvl` int(7) DEFAULT '0',
  `gemSumLvl` int(7) DEFAULT '0',
  `realmSumLvl` int(7) DEFAULT '0',
  `fightSort` int(4) DEFAULT '0' COMMENT '出战顺序',
  `soulArr` varchar(200) DEFAULT NULL COMMENT '{"元婴id":[物品id,剩余血量,今日是否有穿戴过,是否在穿戴]}',
  `wearSoulId` int(11) DEFAULT NULL,
  `talismanNum` int(11) DEFAULT '0',
  `talismanCombat` int(11) DEFAULT '0',
  `wingCombat` int(11) DEFAULT '0' COMMENT '守护精灵战力',
  `holyArr` varchar(200) DEFAULT NULL,
  `holyCombat` int(11) DEFAULT '0',
  `partnerCombat` int(11) DEFAULT '0',
  `magicBookData` text COMMENT '魔书加点数据 {"魔书类型":魔书ID,....}',
  `holyRes` varchar(30) DEFAULT '{"2":0,"4":0,"6":0}' COMMENT '深渊共鸣',
  `magicBookExtraPoint` int(11) DEFAULT NULL COMMENT '魔书额外的点数（使用道具额外增加的点数）',
  PRIMARY KEY (`id`),
  KEY `uw_hero_uid` (`userId`)
) ENGINE=InnoDB AUTO_INCREMENT=3399 DEFAULT CHARSET=utf8mb4 COMMENT='英雄';

