  `isDelete` int(2) DEFAULT '0',
  `taskId` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `uw_mail_uid` (`userId`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COMMENT='邮件';

