-- Table structure for uw_mining
-- ----------------------------
DROP TABLE IF EXISTS `uw_mining`;
CREATE TABLE `uw_mining` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `openTime` datetime DEFAULT NULL COMMENT '开启时间',
  `resourceData` text COMMENT '矿洞资源数据{类型:[矿洞id,剩余资源,[userId,userId,...]],类型:[矿洞id,剩余资源,[userId,userId,...]],...}',
  `mineRecord` text COMMENT '//开采记录[[时间,userId,玩家名,行会名,{道具id:数量,道具id:数量}],[时间,userId,玩家名,行会名,{道具id:数量,道具id:数量}],......]',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='矿洞';

-- ----------------------------
-- Records of uw_mining
-- ----------------------------

-- ----------------------------
-- Table structure for uw_mining_personal
-- ----------------------------
DROP TABLE IF EXISTS `uw_mining_personal`;
CREATE TABLE `uw_mining_personal` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '公会个人信息id',
  `userId` int(11) NOT NULL COMMENT '用户id',
  `miningType` int(4) DEFAULT '0' COMMENT '当前所在矿洞',
  `miningTime` datetime DEFAULT NULL COMMENT '挖矿时间',
  `lastTierChangeTime` datetime DEFAULT NULL COMMENT '最后层数变动时间',
  PRIMARY KEY (`id`),
  KEY `uw_mining_personal_uid` (`userId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='矿洞个人信息';

-- ----------------------------
-- Records of uw_mining_personal
-- ----------------------------

-- ----------------------------
-- Table structure for uw_newfourdays_rank
-- ----------------------------
DROP TABLE IF EXISTS `uw_newfourdays_rank`;
CREATE TABLE `uw_newfourdays_rank` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `userId` int(11) DEFAULT NULL,
  `userName` varchar(50) DEFAULT NULL,
  `iconId` int(4) DEFAULT NULL,
  `userLvl` int(11) DEFAULT NULL,
  `pkWinCount` int(11) DEFAULT NULL,
  `combat` int(11) DEFAULT NULL,
  `rankType` int(11) DEFAULT NULL,
  `rankValue` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `uw_five_rank_uid` (`userId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='新四日目标历史排行榜';

-- ----------------------------
-- Records of uw_newfourdays_rank
-- ----------------------------

-- ----------------------------
-- Table structure for uw_pkout
-- ----------------------------
DROP TABLE IF EXISTS `uw_pkout`;
CREATE TABLE `uw_pkout` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `userId` int(11) DEFAULT '0' COMMENT '用户id',
  `enemyIds` varchar(200) DEFAULT NULL COMMENT '对手组',
  `exEnemyId` int(11) DEFAULT '0' COMMENT '额外的对手',
  `freshTime` datetime DEFAULT NULL COMMENT '上一次刷新对手时间',
  `pkValue` int(6) DEFAULT '0' COMMENT 'pk值',
  `highPkValue` int(6) DEFAULT '0' COMMENT '历史最高pk值',
  `killValue` int(6) DEFAULT '0' COMMENT '杀戮值',
  `pkValueTime` datetime DEFAULT NULL COMMENT 'pk值结算时间',
  `enemyTypes` varchar(200) DEFAULT NULL COMMENT '敌人类型',
  `todayRefreshNum` int(6) DEFAULT '0' COMMENT '每日刷新对手次数',
  `todayRefreshTime` datetime DEFAULT NULL COMMENT '最近每日刷新时间',
  `winCount` int(6) DEFAULT '0' COMMENT '连胜次数',
  `highWinCount` int(6) DEFAULT '0' COMMENT '历史最高连胜次数',
  `accWinCount` int(6) DEFAULT '0' COMMENT '累计胜利次数',
  PRIMARY KEY (`id`),
  KEY `uw_pkOut_uid` (`userId`)
) ENGINE=InnoDB AUTO_INCREMENT=2256 DEFAULT CHARSET=utf8mb4 COMMENT='游戏-野外pk';

-- ----------------------------
-- Records of uw_pkout
-- ----------------------------

-- ----------------------------
-- Table structure for uw_pkout_bak
-- ----------------------------
DROP TABLE IF EXISTS `uw_pkout_bak`;
CREATE TABLE `uw_pkout_bak` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `userId` int(11) DEFAULT '0' COMMENT '用户id',
  `enemyIds` varchar(200) DEFAULT NULL COMMENT '对手组',
  `exEnemyId` int(11) DEFAULT '0' COMMENT '额外的对手',
  `freshTime` datetime DEFAULT NULL COMMENT '上一次刷新对手时间',
  `pkValue` int(6) DEFAULT '0' COMMENT 'pk值',
  `highPkValue` int(6) DEFAULT '0' COMMENT '历史最高pk值',
  `killValue` int(6) DEFAULT '0' COMMENT '杀戮值',
  `pkValueTime` datetime DEFAULT NULL COMMENT 'pk值结算时间',
  `enemyTypes` varchar(200) DEFAULT '0',
  `todayRefreshNum` int(11) DEFAULT '0' COMMENT '每日刷新对手次数',
  `todayRefreshTime` datetime DEFAULT NULL COMMENT '最近每日刷新时间',
  `winCount` int(6) DEFAULT '0' COMMENT '连胜次数',
  `highWinCount` int(6) DEFAULT '0' COMMENT '历史最高连胜次数',
  `accWinCount` int(6) DEFAULT '0' COMMENT '累计胜利次数',
  PRIMARY KEY (`id`),
  KEY `uw_pkOut_bak_uid` (`userId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='游戏-野外pk-备份';

-- ----------------------------
-- Records of uw_pkout_bak
-- ----------------------------

-- ----------------------------
-- Table structure for uw_recharge
-- ----------------------------
DROP TABLE IF EXISTS `uw_recharge`;
CREATE TABLE `uw_recharge` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `userId` int(11) DEFAULT NULL,
  `rechargeId` int(11) DEFAULT NULL,
  `diamond` int(11) DEFAULT NULL COMMENT '充值钻石',
  `rechargeTime` datetime DEFAULT NULL,
  `effTime` datetime DEFAULT NULL COMMENT '生效时间',
  `channelId` int(11) DEFAULT NULL COMMENT '渠道号',
  `transId` varchar(50) DEFAULT NULL COMMENT '业务号',
  `currency` varchar(10) DEFAULT 'CNY' COMMENT '币种,CNY,USD,HKD,TWD',
  `ip` varchar(50) DEFAULT NULL COMMENT 'ip',
  `payMoney` int(11) DEFAULT NULL COMMENT '金额',
  `userLvl` int(4) DEFAULT NULL COMMENT '用户当前等级',
  PRIMARY KEY (`id`),
  KEY `uw_recharge_uid` (`userId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='游戏-充值记录表';

-- ----------------------------
-- Records of uw_recharge
-- ----------------------------

-- ----------------------------
-- Table structure for uw_red_envelope
-- ----------------------------
DROP TABLE IF EXISTS `uw_red_envelope`;
CREATE TABLE `uw_red_envelope` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `redType` int(2) DEFAULT '1' COMMENT '红包类型',
  `userId` int(11) DEFAULT NULL COMMENT '发送者id',
  `guildId` int(11) DEFAULT NULL COMMENT '公会id',
  `diamond` int(11) DEFAULT NULL COMMENT '红包元宝',
  `personNum` int(4) DEFAULT NULL COMMENT '人数',
  `wish` varchar(100) DEFAULT '0' COMMENT '红包祝福',
  `getData` text COMMENT '领取记录[[元宝数,userId],[元宝数,userId]......]',
  `addTime` datetime DEFAULT NULL COMMENT '添加时间',
  `expireTime` datetime DEFAULT NULL COMMENT '过期时间',
  `isDelete` int(2) DEFAULT '0' COMMENT '是否删除',
  `spItemId` int(11) DEFAULT '200' COMMENT '红包物品,默认元宝',
  PRIMARY KEY (`id`),
  KEY `uw_red_envelope_uid` (`userId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='红包';

-- ----------------------------
-- Records of uw_red_envelope
-- ----------------------------

-- ----------------------------
-- Table structure for uw_red_envelope_personal
-- ----------------------------
DROP TABLE IF EXISTS `uw_red_envelope_personal`;
CREATE TABLE `uw_red_envelope_personal` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `userId` int(11) DEFAULT '1' COMMENT '用户id',
  `addUpServer` int(11) DEFAULT '0' COMMENT '累计全服红包',
  `addUpGuild` int(11) DEFAULT '0' COMMENT '累计公会红包',
  `addUpGet` int(4) DEFAULT '0' COMMENT '累计抢得元宝',
  `sendCount` int(11) DEFAULT '0' COMMENT '今日发送次数',
  `lastSendTime` datetime DEFAULT NULL COMMENT '领取记录{"元宝数":userId,"元宝数":userId......}',
  `getData` text COMMENT '发送记录[[份额，用户id，名字],[份额，用户id，名字]..]',
  `exData` varchar(200) DEFAULT NULL COMMENT '扩展数据',
  `exAddUpGet` text COMMENT '累积抢的其他物品',
  PRIMARY KEY (`id`),
  KEY `uw_red_envelope_personal_uid` (`userId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='红包个人信息';

-- ----------------------------
-- Records of uw_red_envelope_personal
-- ----------------------------

-- ----------------------------
-- Table structure for uw_runwat
-- ----------------------------
DROP TABLE IF EXISTS `uw_runwat`;
CREATE TABLE `uw_runwat` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `dateTime` datetime DEFAULT NULL COMMENT '时间',
  `newUser` int(11) DEFAULT '0' COMMENT '新增',
  `active` int(11) DEFAULT '0' COMMENT '活跃',
  `nextDayLeft` float DEFAULT NULL COMMENT '次日留存',
  `weekLeft` float DEFAULT NULL COMMENT '7日留存',
  `runwat` int(11) DEFAULT '0' COMMENT '流水',
  `payCount` int(11) DEFAULT '0' COMMENT '付费用户数',
  `newPay` int(11) DEFAULT '0' COMMENT '新增付费',
  `ARPU` float DEFAULT NULL COMMENT 'ARPU',
  `payRate` float DEFAULT NULL COMMENT '付费率',
  `ARPPU` float DEFAULT NULL COMMENT 'ARPPU',
  `runwatNum` int(11) DEFAULT '0' COMMENT '累计流水',
  `userNum` int(11) DEFAULT '0' COMMENT '累计用户',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='数据分析';

-- ----------------------------
-- Records of uw_runwat
-- ----------------------------

-- ----------------------------
-- Table structure for uw_shop
-- ----------------------------
DROP TABLE IF EXISTS `uw_shop`;
CREATE TABLE `uw_shop` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `userId` int(11) NOT NULL COMMENT '用户id',
  `type` int(4) DEFAULT '0' COMMENT '商店类型',
  `items` varchar(512) DEFAULT NULL COMMENT '普通商店物品[shop模板id,剩余购买次数]',
  `lastTime` datetime DEFAULT NULL COMMENT '普通商店上次刷新时间',
  `refreshCount` int(4) DEFAULT '0' COMMENT '普通商店今日刷新次数',
  `refreshCountResetTime` datetime DEFAULT NULL COMMENT '普通商店刷新次数重置时间',
  PRIMARY KEY (`id`),
  KEY `uw_shop_uid` (`userId`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COMMENT='商店，包括普通商店、竞技场商店和神秘商店';

-- ----------------------------
-- Records of uw_shop
-- ----------------------------

-- ----------------------------
-- Table structure for uw_shop_record
-- ----------------------------
DROP TABLE IF EXISTS `uw_shop_record`;
CREATE TABLE `uw_shop_record` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `userId` int(11) DEFAULT NULL COMMENT '用户id',
  `userLvl` int(11) DEFAULT NULL COMMENT '用户等级',
  `userVip` int(11) DEFAULT NULL COMMENT '用户vip',
  `costGold` int(11) DEFAULT NULL COMMENT '消耗金币',
  `shopType` int(4) DEFAULT NULL COMMENT '商店类型',
  `costDiamond` int(11) DEFAULT NULL COMMENT '消耗元宝',
  `buyItemId` int(11) DEFAULT NULL COMMENT '购买物品',
  `buyAmount` int(11) DEFAULT NULL COMMENT '购买数量',
  `buyTime` datetime DEFAULT NULL COMMENT '购买时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COMMENT='游戏-商店购买记录';

-- ----------------------------
-- Records of uw_shop_record
-- ----------------------------

-- ----------------------------
-- Table structure for uw_sys_red_envelope
-- ----------------------------
DROP TABLE IF EXISTS `uw_sys_red_envelope`;
CREATE TABLE `uw_sys_red_envelope` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `userId` int(11) DEFAULT '0' COMMENT '发送者id,系统为0',
  `sendName` varchar(20) DEFAULT '系统' COMMENT '发送者名称',
  `redType` int(2) DEFAULT '1' COMMENT '红包类型',
  `guildId` int(11) DEFAULT NULL COMMENT '公会id',
  `spItemId` int(11) DEFAULT NULL COMMENT '红包物品',
  `amount` int(11) DEFAULT '0' COMMENT '物品数量',
  `viewAmount` int(11) DEFAULT '0' COMMENT '显示数量',
  `personNum` int(4) DEFAULT '0' COMMENT '人数',
  `wish` varchar(100) DEFAULT NULL COMMENT '红包祝福',
  `limitZone` text COMMENT '每人限额区间',
  `addTime` datetime DEFAULT NULL COMMENT '添加时间',
  `isDeal` int(2) DEFAULT '0' COMMENT '处理状态',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='游戏触发（或后台发送的）的发送给玩家的红包';

-- ----------------------------
-- Records of uw_sys_red_envelope
-- ----------------------------

-- ----------------------------
-- Table structure for uw_task
-- ----------------------------
DROP TABLE IF EXISTS `uw_task`;
CREATE TABLE `uw_task` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `userId` int(11) DEFAULT NULL COMMENT '用户id',
  `dailyTasks` varchar(500) DEFAULT NULL COMMENT '日常任务。{"任务id":[完成数量,是否领取],"任务id":[完成数量,是否领取],.....}',
  `vitality` int(4) DEFAULT '0' COMMENT '活跃度',
  `vitalityChests` varchar(50) DEFAULT NULL COMMENT '活跃度宝箱领取  【是否领取，是否领取，。。】 下标代表宝箱位置',
  `refreshTime` datetime DEFAULT NULL COMMENT '日常数据最后修改时间',
  `tasks` text COMMENT '成就任务。{"任务子类型":当前正在进行任务,"任务子类型":当前正在进行任务,.....}',
  `tasksValue` text COMMENT '成就任务完成数据  {"子类型":数量,"子类型":数量,...}',
  `doneTasks` text COMMENT '已领取的成就任务。 格式为[taskId1, taskId2]',
  `weekTasks` varchar(500) DEFAULT NULL,
  `weekRefreshTime` datetime DEFAULT NULL,
  `guideDoneTasks` varchar(500) DEFAULT NULL,
  `wVitality` int(11) DEFAULT '0',
  `wVitalityChests` varchar(50) DEFAULT NULL,
  `wVitalityRefreshTime` datetime DEFAULT NULL,
  `heroTasks` text COMMENT '英雄传记',
  `entrustTasks` text COMMENT '紧急委托任务',
  PRIMARY KEY (`id`),
  KEY `uw_task_uid` (`userId`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='任务表';

-- ----------------------------
-- Records of uw_task
-- ----------------------------

-- ----------------------------
-- Table structure for uw_treasure
-- ----------------------------
DROP TABLE IF EXISTS `uw_treasure`;
CREATE TABLE `uw_treasure` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `userId` int(11) DEFAULT NULL COMMENT '拥有者id',
  `treasureId` int(11) DEFAULT NULL COMMENT '秘宝id',
  `openTime` datetime DEFAULT NULL COMMENT '开启时间',
  `isOpen` int(2) DEFAULT '1' COMMENT '是否有效',
  `items` text COMMENT '开出物品',
  `isDelete` int(2) DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='秘宝信息表';

-- ----------------------------
-- Records of uw_treasure
-- ----------------------------

-- ----------------------------
-- Table structure for uw_treasurerecord
-- ----------------------------
DROP TABLE IF EXISTS `uw_treasurerecord`;
CREATE TABLE `uw_treasurerecord` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `recordType` int(4) DEFAULT NULL COMMENT '记录类型',
  `userId` int(11) DEFAULT NULL COMMENT '玩家id',
  `guildName` varchar(20) DEFAULT NULL COMMENT '公会名',
  `userVip` int(4) DEFAULT NULL COMMENT 'vip等级',
  `userName` varchar(20) DEFAULT NULL COMMENT '玩家名',
  `medalTitle` int(11) DEFAULT NULL COMMENT '勋章称号',
  `treasureId` int(11) DEFAULT NULL COMMENT '秘宝id',
  `items` text COMMENT '掉落物品',
  `recordDate` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='秘宝争夺记录';

-- ----------------------------
-- Records of uw_treasurerecord
-- ----------------------------

-- ----------------------------
-- Table structure for uw_user
-- ----------------------------
DROP TABLE IF EXISTS `uw_user`;
CREATE TABLE `uw_user` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `accountId` int(11) DEFAULT '0' COMMENT '账号id',
  `iconId` int(4) DEFAULT NULL,
  `nickName` varchar(50) DEFAULT NULL COMMENT '昵称',
  `gold` int(11) unsigned DEFAULT '0' COMMENT '金币',
  `diamond` int(11) DEFAULT '0' COMMENT '钻石',
  `giveDiamond` int(11) DEFAULT '0' COMMENT '绑定钻石，即送的钻石',
  `buyDiamond` int(11) DEFAULT '0' COMMENT '非绑定钻石，即购买的钻石',
  `lvl` int(4) DEFAULT '0' COMMENT '等级(不同于英雄等级)',
  `expc` int(11) unsigned DEFAULT '0' COMMENT '经验',
  `combat` int(11) DEFAULT '0' COMMENT '战力',
  `vip` int(4) DEFAULT '0' COMMENT 'VIP等级',
  `vipScore` int(11) DEFAULT '0' COMMENT 'VIP积分',
  `dScore` int(11) unsigned DEFAULT '0' COMMENT ' ',
  `strength` int(4) DEFAULT NULL,
  `strengthReTime` datetime DEFAULT NULL,
  `signName` varchar(100) DEFAULT NULL COMMENT '签名',
  `honor` int(7) DEFAULT '0' COMMENT '荣誉值',
  `bag` mediumtext COMMENT '背包(只存放静态物品，格式：{"物品id":数量,"物品id":数量.............})',
  `equipBag` longtext COMMENT '装备背包 {"1":[物品id,[随到的属性值],评价,是否穿戴],...}  "1":指定id,累加上去的',
  `equipBagBuyCount` int(4) DEFAULT '0' COMMENT '装备背包购买次数',
  `honorData` text COMMENT '成就数据\n            {"id":[是否完成，是否领取],"id":[是否完成，是否领取],..........}',
  `blueDiamond` varchar(200) DEFAULT '' COMMENT '蓝钻标记，为一个对象，key为dsConsts.BlueDiamond中的定义',
  `sign` varchar(50) DEFAULT NULL COMMENT '签到数据,[签到次数,最近一次签到时间]',
  `activity` text COMMENT '{"活动id":数据}\n            数据格式：\n            首充:[领取次数]，\n            七天登陆：[次数,次数...]\n            每日限购:[[次数,时间],[次数,时间]..........]\n            每日累充:[领取时间,领取时间,..........]\n            全部累充:[次数,次数..........]\n            每日消费:[领取时间,领取时间,..........]\n            全部',
  `record` text COMMENT '记录数据',
  `exData` text COMMENT '刷新数据\n            {key:value}\n            具体看c_prop的userExData',
  `counts` varchar(256) DEFAULT NULL COMMENT '今日次数列表，是一个数组，对应各自系统的次数。',
  `countsRefreshTime` text COMMENT '今日次数列表刷新时间【】数组对应下标',
  `lastUpdateTime` datetime DEFAULT NULL COMMENT '更新时间',
  `serverId` int(4) DEFAULT NULL,
  `lastSkillTime` datetime DEFAULT NULL COMMENT '最后点技能时间',
  `skillCd` int(7) DEFAULT '0' COMMENT '技能CD',
  `isOpenPk` int(2) DEFAULT '0' COMMENT '是否开启pk',
  `prestige` int(7) DEFAULT '0' COMMENT '声望',
  `redPointData` varchar(100) DEFAULT NULL COMMENT '红点数据',
  `robotId` int(11) DEFAULT '0' COMMENT '机器人id',
  `createTime` datetime DEFAULT NULL COMMENT '添加时间',
  `sdkChannelId` varchar(20) DEFAULT NULL COMMENT 'sdk渠道号',
  `serverIndexId` int(11) DEFAULT '0' COMMENT '服务器索引',
  `onlineLootData` varchar(200) DEFAULT NULL COMMENT '在线掉落数据',
  `coffersPoints` int(11) DEFAULT '0' COMMENT '国库累计积分',
  `todayCoffersPoints` int(11) DEFAULT '0' COMMENT '国库每日积分',
  `medalTitle` int(11) DEFAULT '0' COMMENT '勋章称号',
  `medalData` text COMMENT '勋章数据',
  `genuineQi` int(11) DEFAULT '0' COMMENT '真气',
  `propertyData` text COMMENT '属性数据',
  `coffersKillNum` int(6) DEFAULT '0' COMMENT '国库击杀人数',
  `isKing` int(2) DEFAULT '0' COMMENT '是否霸主',
  `rebirthLvl` int(4) DEFAULT '0' COMMENT '转生等级',
  `rebirthExp` bigint(11) DEFAULT '0' COMMENT '转生经验',
  `isOpenIn` int(2) DEFAULT '0',
  `infuseExpc` bigint(20) DEFAULT '0',
  `highPaTa` int(4) DEFAULT '0' COMMENT '通天塔最高层数',
  `heroData` text,
  `medalExData` text,
  `medalDoneData` text,
  `buff` varchar(256) DEFAULT NULL COMMENT '玩家buff数据',
  `employData` text,
  `tap` int(11) DEFAULT '0' COMMENT 'tap点击战力',
  `achieveLvl` int(4) DEFAULT '0',
  `achieveExp` int(4) DEFAULT '0',
  `medalNum` int(11) DEFAULT '0',
  `cybExp` int(11) DEFAULT '0',
  `cybLvl` int(4) DEFAULT '1',
  `jxExp` int(11) DEFAULT '0' COMMENT '军衔经验',
  `jxLvl` int(4) DEFAULT '1' COMMENT '军衔等级',
  `heroNum` int(11) DEFAULT '0',
  `loginDays` text COMMENT '登录日期记录 []',
  `cup` int(11) DEFAULT '0',
  `capsuleData` varchar(256) DEFAULT NULL,
  `channelId` int(11) DEFAULT '0' COMMENT '渠道id',
  `noble` varchar(1024) DEFAULT NULL,
  `magicLvl` int(7) DEFAULT '0' COMMENT '魔导等级',
  `elfWakingData` text COMMENT '精灵觉醒数据 {"精灵id":精灵觉醒等级id,….}',
  `elfWakingAppear` int(11) DEFAULT '0' COMMENT '精灵觉醒现身id',
  PRIMARY KEY (`id`),
  KEY `uw_user_aid` (`accountId`)
) ENGINE=InnoDB AUTO_INCREMENT=2256 DEFAULT CHARSET=utf8mb4 COMMENT='角色，账号进入到每个服中扮演的角色。';

-- ----------------------------
-- Records of uw_user
-- ----------------------------

-- ----------------------------
-- Table structure for uw_user_bak
-- ----------------------------
DROP TABLE IF EXISTS `uw_user_bak`;
CREATE TABLE `uw_user_bak` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `accountId` int(11) DEFAULT '0' COMMENT '账号id',
  `iconId` int(4) DEFAULT NULL,
  `nickName` varchar(50) DEFAULT NULL COMMENT '昵称',
  `lvl` int(4) DEFAULT '0' COMMENT '等级(不同于英雄等级)',
  `expc` int(11) unsigned DEFAULT '0' COMMENT '经验',
  `combat` int(11) DEFAULT '0' COMMENT '战力',
  `vip` int(4) DEFAULT '0' COMMENT 'VIP等级',
  `vipScore` int(11) DEFAULT '0' COMMENT 'VIP积分',
  `exData` text,
  `createTime` datetime DEFAULT NULL COMMENT '创建时间',
  `achieveLvl` int(4) DEFAULT '0',
  `achieveExp` int(4) DEFAULT '0',
  `highPaTa` int(4) DEFAULT '0',
  `heroNum` int(11) DEFAULT '0',
  `rebirthLvl` int(11) DEFAULT '0',
  `rebirthExp` bigint(11) DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `uw_user_aid` (`accountId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='角色，账号进入到每个服中扮演的角色。';

-- ----------------------------
-- Records of uw_user_bak
-- ----------------------------

-- ----------------------------
-- Table structure for uw_user_coupon
