DROP TABLE IF EXISTS `uw_user_coupon`;
CREATE TABLE `uw_user_coupon` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '序号',
  `codeName` varchar(50) NOT NULL COMMENT '兑换码批次',
  `userId` int(11) NOT NULL COMMENT '玩家id',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='游戏-用户兑换码(UserCouponEntity)';

