-- ----------------------------
-- Table structure for uw_user_rank
-- ----------------------------
DROP TABLE IF EXISTS `uw_user_rank`;
CREATE TABLE `uw_user_rank` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '排名',
  `userId` int(11) DEFAULT NULL COMMENT '领主id',
  `userName` varchar(50) DEFAULT NULL COMMENT '领主名称',
  `iconId` int(4) DEFAULT NULL,
  `userLvl` int(11) DEFAULT NULL COMMENT '英雄id',
  `blueDiamond` varchar(200) DEFAULT '' COMMENT '蓝钻标记',
  `rankValue` int(11) DEFAULT '0' COMMENT '排名数值',
  `rankType` int(11) DEFAULT '0' COMMENT '排名类型',
  `pkWinCount` int(11) DEFAULT NULL COMMENT '英雄等级',
  `combat` int(11) DEFAULT NULL COMMENT '战力',
  `guildName` varchar(50) DEFAULT NULL COMMENT '公会名称',
  PRIMARY KEY (`id`),
  KEY `uw_user_rank_uid` (`userId`)
) ENGINE=InnoDB AUTO_INCREMENT=92 DEFAULT CHARSET=utf8mb4 COMMENT='用户排行榜';

